{
  "@context":"https://schema.org",
  "@type":"FAQPage",
  "mainEntity":[
    {"@type":"Question","name":"How long should a detailer wait before following up on a quote?","acceptedAnswer":{"@type":"Answer","text":"There is no universal rule, but a practical starting point is one short follow-up around 24 to 48 hours after sending the quote, followed by one final check-in a few days later if the lead remains silent. Test timing against your own booking rate and customer feedback."}},
    {"@type":"Question","name":"How many times should I follow up after sending a detailing estimate?","acceptedAnswer":{"@type":"Answer","text":"For many small detailing businesses, two or three total follow-up touches are enough to test whether a lead is still active without creating an endless chase. Stop when the customer declines, asks not to be contacted, or clearly goes cold."}},
    {"@type":"Question","name":"Should auto detailers automate quote follow-up?","acceptedAnswer":{"@type":"Answer","text":"Automation is most useful when manual follow-up is being forgotten, delayed, or repeated across enough estimates to consume meaningful time. Smaller operators with low quote volume can start with saved templates and reminders before paying for a larger CRM."}},
    {"@type":"Question","name":"What should a detailing quote follow-up message say?","acceptedAnswer":{"@type":"Answer","text":"Keep it short, reference the vehicle or service, offer to answer questions, and provide one clear next step such as booking or choosing a time. Avoid guilt, pressure, or repeated discounting by default."}}
  ]
}

{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[
{"@type":"Question","name":"Should mobile detailers charge a travel fee?","acceptedAnswer":{"@type":"Answer","text":"There is no universal rule. Many operators include nearby travel in package pricing and add a fee, minimum job value or service-zone rule only beyond a defined radius. The right policy depends on travel time, fuel, vehicle costs and local demand."}},
{"@type":"Question","name":"Is mileage or travel time better for setting a fee?","acceptedAnswer":{"@type":"Answer","text":"Either can work. Mileage is easy to standardize, while travel time may better capture traffic and lost production time. Some businesses use zones or a free radius, then add a flat or distance-based surcharge outside it."}},
{"@type":"Question","name":"Can booking software apply travel fees automatically?","acceptedAnswer":{"@type":"Answer","text":"Some platforms can. OrbisX publishes mobile-service controls for free travel radius and distance surcharges. Housecall Pro supports service zones with optional trip charges that can be applied during Online Booking."}},
{"@type":"Question","name":"Should I accept very distant mobile detailing jobs?","acceptedAnswer":{"@type":"Answer","text":"Only when the job value and schedule justify the travel. A minimum job value, grouped appointments in the same area or a surcharge can help protect margin."}}
]}

